insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('family-images','family-images',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;
create policy "members read family images" on storage.objects for select to authenticated using(bucket_id='family-images' and (storage.foldername(name))[1]::uuid in(select private.user_household_ids()));
create policy "members upload family images" on storage.objects for insert to authenticated with check(bucket_id='family-images' and (storage.foldername(name))[1]::uuid in(select private.user_household_ids()));
create policy "members delete family images" on storage.objects for delete to authenticated using(bucket_id='family-images' and (storage.foldername(name))[1]::uuid in(select private.user_household_ids()));
